+// Write USDC ERC-20 balance by overwriting storage slot.
+// Arc USDC is a standard OpenZeppelin ERC-20; balances live at slot
+//   keccak256(abi.encode(account, 0))  — mapping at slot 0
+async function giveUsdc(addr: Address, amount: bigint) {
+  // ERC-20 balanceOf mapping is at storage slot 0 (standard OZ layout)
+  const slot = keccak256(
+    encodeAbiParameters(
+      parseAbiParameters("address, uint256"),
+      [addr, 0n]
+    )
+  );
+  await rpc("anvil_setStorageAt", [USDC_ADDR, slot, pad(toHex(amount), { size: 32 })]);
+}
