+async function sendTx(
+  from: Address,
+  to: Address,
+  data: Hex,
+  label: string
+): Promise<{ hash: Hex; block: bigint; gasUsed: bigint }> {
+  const hash = await rpc("eth_sendTransaction", [{ from, to, data, gas: "0x7A120" }]) as Hex;
+  // Wait for receipt
+  let receipt: Record<string, unknown> | null = null;
+  for (let i = 0; i < 30; i++) {
+    receipt = await rpc("eth_getTransactionReceipt", [hash]) as Record<string, unknown> | null;
+    if (receipt) break;
+    await new Promise(r => setTimeout(r, 200));
+  }
+  if (!receipt) throw new Error(`${label}: receipt not found for ${hash}`);
+  if (receipt.status !== "0x1") {
+    throw new Error(`${label}: tx REVERTED hash=${hash} status=${receipt.status}`);
+  }
+  return {
+    hash,
+    block: BigInt(receipt.blockNumber as string),
+    gasUsed: BigInt(receipt.gasUsed as string),
+  };
+}
